<script setup>
import { updateApplication as wayfinderUpdateApplication1, destroyInsight as wayfinderDestroyInsight2, closeJob as wayfinderCloseJob3, storeInsight as wayfinderStoreInsight6, storeJob as wayfinderStoreJob7, updateInsight as wayfinderUpdateInsight8, updateJob as wayfinderUpdateJob9 } from './../../actions/App/Http/Controllers/StaffPublishingController';
