import { Link, router, useForm } from '@inertiajs/vue3';
import { reactive } from 'vue';

const props = defineProps({ insights: Array, jobs: Array, applications: Array, canManageApplications: Boolean });
const insight = useForm({ title: '', type: 'article', category: '', excerpt: '', cover_image: '', cover_upload: null, survey_url: '', body: '', status: 'draft' });
const job = useForm({ title: '', company: '', location: 'Remote', workplace_type: 'remote', employment_type: 'full_time', seniority: '', salary_range: '', summary: '', description: '', skills: '', application_url: '', expires_at: '', status: 'draft' });
const insightEdits = reactive(Object.fromEntries(props.insights.map((item) => [item.id, { title: item.title, slug: item.slug, type: item.type, category: item.category || '', excerpt: item.excerpt || '', body: item.body, cover_image: item.cover_image || '', cover_upload: null, survey_url: item.survey_url || '', status: item.status }])));
