sight.errors.survey_url">{{ insight.errors.survey_url }}</small></label><label>Content<textarea v-model="insight.body" rows="8" required :placeholder="insight.type === 'survey' ? 'Explain the purpose, who should respond, and how responses will be used.' : insight.type === 'report' ? 'Write the report findings, methodology, and sources.' : 'Write your content.'"></textarea><small v-if="insight.errors.body">{{ insight.errors.body }}</small></label><div class="publish-action"><select v-model="insight.status"><option value="draft">Save as draft</option><option value="published">Publish now</option></select><button class="button button-dark" :disabled="insight.processing">{{ insight.status === 'published' ? 'Publish insight' : 'Save draft' }} <UiIcon name="arrow-up-right" :size="13" /></button></div></form>
