s="form-row"><label>External application URL<input v-model="jobEdits[item.id].application_url" type="url"></label><label>Deadline<input v-model="jobEdits[item.id].expires_at" type="date"></label></div><div class="publish-action"><button class="button button-dark">Save changes</button><select v-model="jobEdits[item.id].status"><option value="draft">Draft</option><option value="pending_review">Pending review</option><option value="published">Published</option><option value="closed">Closed</option></select><button type="button" class="record-delete" @click="closeJob(item.id)">Close listing</button></div></form></details><p v-if="!jobs.length" class="no-items">No opportunities posted yet.</p></section>
